<?php
require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../includes/auth.php';requireRole('admin');
$admin=currentUser();$pageTitle='Collector Management | Eco-Loop';
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['collector_id']??0,FILTER_VALIDATE_INT)?:0;$connection=db();$transactionOpen=false;
 try{
  if($action==='create'){
   $name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['mobile_number']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
   if($name===''||mb_strlen($name)>150||$phone===''||mb_strlen($phone)>20||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12)throw new RuntimeException('Enter a valid name, contact number, email, and initial password of at least 12 characters.');
   $connection->begin_transaction();$transactionOpen=true;$role='collector';$status='active';$hash=password_hash($password,PASSWORD_DEFAULT);
   $u=$connection->prepare('INSERT INTO users (full_name,mobile_number,email,password_hash,role,status) VALUES (?,?,?,?,?,?)');$u->bind_param('ssssss',$name,$phone,$email,$hash,$role,$status);$u->execute();$userId=(int)$u->insert_id;$u->close();
   $c=$connection->prepare('INSERT INTO collectors (user_id,full_name,mobile_number,email,status) VALUES (?,?,?,?,?)');$c->bind_param('issss',$userId,$name,$phone,$email,$status);$c->execute();$collectorId=(int)$c->insert_id;$c->close();
   logAdminAction((int)$admin['id'],'Collector account created','Collector #'.$collectorId.' / user #'.$userId.' / '.$email);$connection->commit();$transactionOpen=false;setFlash('success','Collector account created. Share the initial password securely with the collector.');
  }elseif($action==='status'&&$id>0){
   $status=(string)($_POST['status']??'');if(!in_array($status,['active','inactive'],true))throw new RuntimeException('Choose a valid collector status.');$connection->begin_transaction();$transactionOpen=true;$lock=$connection->prepare('SELECT user_id,full_name,email FROM collectors WHERE id=? FOR UPDATE');$lock->bind_param('i',$id);$lock->execute();$collector=$lock->get_result()->fetch_assoc();$lock->close();if(!$collector)throw new RuntimeException('Collector not found.');$stmt=$connection->prepare('UPDATE collectors SET status=? WHERE id=?');$stmt->bind_param('si',$status,$id);$stmt->execute();$stmt->close();if($collector['user_id']){$stmt=$connection->prepare('UPDATE users SET status=? WHERE id=? AND role="collector"');$stmt->bind_param('si',$status,$collector['user_id']);$stmt->execute();$stmt->close();}logAdminAction((int)$admin['id'],'Collector status changed','Collector #'.$id.' '.$collector['email'].' set to '.$status);$connection->commit();$transactionOpen=false;setFlash('success','Collector access updated.');
  }else throw new RuntimeException('Choose a valid collector action.');
 }catch(RuntimeException $e){if($transactionOpen)$connection->rollback();setFlash('error',$e->getMessage());}catch(Throwable $e){if($transactionOpen)$connection->rollback();error_log('EcoLoop collector management failed: '.$e->getMessage());setFlash('error','The collector change could not be saved. Check for a duplicate email address.');}
 redirect('admin/collectors.php');
}
$collectors=db()->query('SELECT c.id,c.user_id,c.full_name,c.mobile_number,c.email,c.status,c.created_at FROM collectors c ORDER BY c.status DESC,c.full_name')->fetch_all(MYSQLI_ASSOC);
require __DIR__.'/../includes/header.php';
?>
<div class="dashboard-shell"><?php require __DIR__.'/../includes/navigation.php';?><main class="main-content"><div class="page-header"><div><span class="eyebrow">Operations</span><h1>Collector Management</h1></div></div>
<section class="content-card"><h2>Add collector</h2><p>This creates a role-restricted collector login and an assignment record. Share the initial password privately.</p><form method="post" class="request-grid"><?php echo csrf_field();?><input type="hidden" name="action" value="create"><div class="field-group"><label>Full name</label><input name="full_name" maxlength="150" required></div><div class="field-group"><label>Contact number</label><input name="mobile_number" maxlength="20" required></div><div class="field-group"><label>Email</label><input type="email" name="email" maxlength="150" required></div><div class="field-group"><label>Initial password (12+ characters)</label><input type="password" name="password" minlength="12" autocomplete="new-password" required></div><div class="form-actions full-span"><button class="btn btn-primary">Create collector</button></div></form></section>
<section class="content-card"><h2>Collectors</h2><?php if($collectors):?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Status</th><th>Added</th><th>Access</th></tr></thead><tbody><?php foreach($collectors as $collector):?><tr><td><?php echo e($collector['full_name']);?><br><small><?php echo e($collector['email']);?></small></td><td><?php echo e($collector['mobile_number']);?></td><td><?php echo e(ucfirst($collector['status']));?></td><td><?php echo e(date('M j, Y',strtotime($collector['created_at'])));?></td><td><form method="post" class="inline-form"><?php echo csrf_field();?><input type="hidden" name="action" value="status"><input type="hidden" name="collector_id" value="<?php echo(int)$collector['id'];?>"><select name="status"><option value="active" <?php echo $collector['status']==='active'?'selected':'';?>>Active</option><option value="inactive" <?php echo $collector['status']==='inactive'?'selected':'';?>>Inactive</option></select><button class="btn btn-secondary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No collector records. Add verified staff accounts as needed.</p><?php endif;?></section>
</main></div><?php require __DIR__.'/../includes/footer.php';?>
